const garmin = $("Query Garmin 7 Days").all().map(function(i) { return i.json; });
const rides = $("Query Recent Rides").all().map(function(i) { return i.json; });
const workouts = $("Query Recent Workouts").all().map(function(i) { return i.json; });

const withHRV = garmin.filter(function(d) { return d.hrv; });
const withSleep = garmin.filter(function(d) { return d.sleep_score; });
const avgHRV = withHRV.length ? Math.round(withHRV.reduce(function(s,d){return s+Number(d.hrv);},0)/withHRV.length) : null;
const avgSleep = withSleep.length ? Math.round(withSleep.reduce(function(s,d){return s+Number(d.sleep_score);},0)/withSleep.length) : null;
const latest = garmin.length ? garmin[0] : null;
const withWeight = garmin.filter(function(d){return d.weight_kg;});
const latestWeight = withWeight.length ? withWeight[0] : null;

const rideCount = rides.length;
const totalDistanceMi = rides.reduce(function(s,r){return s+(Number(r.distance_m)||0);},0)/1609.34;
const npList = rides.filter(function(r){return r.weighted_average_watts;}).map(function(r){return Number(r.weighted_average_watts);});
const bestNP = npList.length ? Math.max.apply(null,npList) : null;
const workoutCount = workouts.length;
const workoutNames = workouts.map(function(w){return w.title;}).join(", ");

var lines = [];
lines.push("WEEKLY TRAINING DIGEST");
lines.push("");
lines.push("RECOVERY");
lines.push("HRV avg: " + (avgHRV ? avgHRV+" ms" : "no data"));
lines.push("Sleep avg: " + (avgSleep ? avgSleep+"/100" : "no data"));
if (latest) {
  lines.push("Acute load: " + (latest.acute_training_load||"n/a"));
  lines.push("Chronic load: " + (latest.chronic_training_load||"n/a"));
  lines.push("Status: " + (latest.training_status||"n/a"));
}
if (latestWeight) {
  lines.push("Weight: " + Math.round(Number(latestWeight.weight_kg)*2.20462)+" lb ("+latestWeight.body_fat_pct+"% bf)");
}
lines.push("");
lines.push("RIDING (" + rideCount + " rides)");
lines.push("Distance: " + totalDistanceMi.toFixed(1) + " mi");
if (bestNP) lines.push("Best NP: " + Math.round(bestNP) + "W");
lines.push("");
lines.push("LIFTING (" + workoutCount + " sessions)");
if (workoutNames) lines.push(workoutNames);
lines.push("");
lines.push("Open Claude for full analysis");
return [{ json: { message: lines.join("\n"), title: "Weekly Training Digest" } }];
